"""Threaded HTTP server exposing the public record and key protocol."""

import json
import re
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit

from .config import Config
from .ledger import Ledger, LedgerError

IDENT_PATTERN = re.compile(r"[A-Za-z0-9_-]{1,64}\Z")
MAX_PLAINTEXT_BYTES = 65536
TENANT_HEADER = "X-Tenant-ID"


def is_ident(value: object) -> bool:
    return isinstance(value, str) and IDENT_PATTERN.fullmatch(value) is not None


class LedgerServer(ThreadingHTTPServer):
    daemon_threads = True

    def __init__(self, address: tuple[str, int], config: Config):
        self.config = config
        self.ledger = Ledger(config)
        super().__init__(address, LedgerHandler)

    def server_close(self) -> None:
        try:
            self.ledger.close()
        finally:
            super().server_close()


class LedgerHandler(BaseHTTPRequestHandler):
    server: LedgerServer

    def send_json(self, status: int, value: dict) -> None:
        payload = json.dumps(value, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def error(self, status: int, code: str) -> None:
        self.send_json(status, {"error": code})

    def tenant(self) -> str | None:
        value = self.headers.get(TENANT_HEADER)
        return value if is_ident(value) else None

    def read_json_object(self) -> dict | None:
        try:
            length = int(self.headers.get("Content-Length", "0"))
        except (TypeError, ValueError):
            return None
        if length < 0:
            return None
        try:
            raw = self.rfile.read(length)
            value = json.loads(raw.decode("utf-8"))
        except (ValueError, UnicodeDecodeError):
            return None
        return value if isinstance(value, dict) else None

    # -- routing -----------------------------------------------------------

    def do_GET(self) -> None:
        path = urlsplit(self.path).path
        try:
            if path == "/health":
                self.send_json(200, {"status": "ok", "service": "cipher-ledger"})
            elif path == "/v1/keys":
                self.send_json(200, {"active_version": self.server.ledger.active_version})
            elif path.startswith("/v1/records/"):
                self.get_record(path[len("/v1/records/") :])
            else:
                self.error(404, "not_found")
        except LedgerError as exc:
            self.error(exc.status, exc.code)
        except Exception:
            # Never leak stack traces or crypto library details.
            self.error(500, "internal_error")

    def do_POST(self) -> None:
        path = urlsplit(self.path).path
        try:
            if path == "/v1/records":
                self.create_record()
            elif path == "/v1/keys/rotate":
                self.rotate_keys()
            else:
                self.error(404, "not_found")
        except LedgerError as exc:
            self.error(exc.status, exc.code)
        except Exception:
            self.error(500, "internal_error")

    # -- endpoints ---------------------------------------------------------

    def get_record(self, record_id: str) -> None:
        tenant = self.tenant()
        if tenant is None or not is_ident(record_id):
            self.error(400, "invalid_request")
            return
        result = self.server.ledger.read(tenant, record_id)
        self.send_json(200, result)

    def create_record(self) -> None:
        tenant = self.tenant()
        payload = self.read_json_object()
        if tenant is None or payload is None:
            self.error(400, "invalid_request")
            return
        record_id = payload.get("id")
        plaintext = payload.get("plaintext")
        if not is_ident(record_id) or not isinstance(plaintext, str):
            self.error(400, "invalid_request")
            return
        try:
            if len(plaintext.encode("utf-8")) > MAX_PLAINTEXT_BYTES:
                self.error(400, "invalid_request")
                return
        except UnicodeEncodeError:
            self.error(400, "invalid_request")
            return
        version = self.server.ledger.create(tenant, record_id, plaintext)
        self.send_json(201, {"id": record_id, "key_version": version})

    def rotate_keys(self) -> None:
        payload = self.read_json_object()
        if payload is None:
            self.error(400, "invalid_request")
            return
        version = payload.get("version")
        # Booleans are ints in Python; they are not accepted as versions.
        if type(version) is not int or version < 1:
            self.error(400, "invalid_request")
            return
        active, rewrapped = self.server.ledger.rotate(version)
        self.send_json(200, {"active_version": active, "rewrapped": rewrapped})

    def log_message(self, format: str, *args) -> None:
        # Access logs contain only the usual request line and status information;
        # request bodies, plaintext and key material are never logged.
        super().log_message(format, *args)

"""Tenant-scoped record storage with envelope encryption and key rotation.

All operations take one process-wide re-entrant lock so the results of
concurrent creates, reads and rotations are equivalent to some total serial
ordering. Rotation verifies every old envelope first and only then performs a
single transactional write, so a damaged envelope or a storage failure leaves
the active version and all records exactly as they were before the request.
"""

import sqlite3
import threading

from . import envelope
from .config import Config
from .database import connect, initialize


class LedgerError(Exception):
    """Application-level error mapped to an HTTP status and code."""

    def __init__(self, status: int, code: str):
        super().__init__(code)
        self.status = status
        self.code = code


def conflict() -> LedgerError:
    return LedgerError(409, "conflict")


def not_found() -> LedgerError:
    return LedgerError(404, "not_found")


def integrity() -> LedgerError:
    return LedgerError(422, "integrity_error")


def storage() -> LedgerError:
    return LedgerError(503, "storage_error")


class Ledger:
    def __init__(self, config: Config):
        initialize(config.database, config.active_version)
        self._keys = dict(config.keys)
        self._connection = connect(config.database)
        self._lock = threading.RLock()
        try:
            row = self._connection.execute(
                "SELECT value FROM service_metadata WHERE name='active_version'"
            ).fetchone()
            active = int(row[0])
        except (TypeError, ValueError, sqlite3.Error) as exc:
            raise ValueError("Invalid persisted active version") from exc
        if active not in self._keys:
            raise ValueError("Invalid keyring configuration")
        self._active_version = active

    @property
    def active_version(self) -> int:
        with self._lock:
            return self._active_version

    def close(self) -> None:
        with self._lock:
            self._connection.close()

    # -- records -----------------------------------------------------------

    def create(self, tenant: str, record_id: str, plaintext: str) -> int:
        """Create a record. Returns the key version used. Duplicate -> 409."""
        with self._lock:
            version = self._active_version
            sealed = envelope.seal(self._keys, version, tenant, record_id, plaintext)
            try:
                with self._connection:
                    self._connection.execute(
                        "INSERT INTO records "
                        "(tenant, id, key_version, nonce, ciphertext, wrap_nonce, wrapped_key) "
                        "VALUES (?, ?, ?, ?, ?, ?, ?)",
                        (
                            tenant,
                            record_id,
                            sealed["key_version"],
                            sealed["nonce"],
                            sealed["ciphertext"],
                            sealed["wrap_nonce"],
                            sealed["wrapped_key"],
                        ),
                    )
            except sqlite3.IntegrityError:
                # PRIMARY KEY (tenant, id) violation -> record already exists.
                raise conflict() from None
            except sqlite3.Error:
                raise storage() from None
            return version

    def read(self, tenant: str, record_id: str) -> dict:
        with self._lock:
            try:
                row = self._connection.execute(
                    "SELECT key_version, nonce, ciphertext, wrap_nonce, wrapped_key "
                    "FROM records WHERE tenant=? AND id=?",
                    (tenant, record_id),
                ).fetchone()
            except sqlite3.Error:
                raise storage() from None
            if row is None:
                raise not_found()
            try:
                plaintext = envelope.open_envelope(self._keys, tenant, record_id, row)
            except envelope.EnvelopeIntegrityError:
                raise integrity() from None
            return {"id": record_id, "plaintext": plaintext, "key_version": row["key_version"]}

    # -- keys --------------------------------------------------------------

    def rotate(self, target: int) -> tuple[int, int]:
        """Rotate all records to ``target``. Returns (active_version, rewrapped)."""
        with self._lock:
            if target < self._active_version:
                raise LedgerError(409, "version_conflict")
            if target == self._active_version:
                return self._active_version, 0
            if target not in self._keys:
                raise LedgerError(400, "invalid_version")

            try:
                rows = self._connection.execute(
                    "SELECT tenant, id, key_version, nonce, ciphertext, wrap_nonce, wrapped_key "
                    "FROM records"
                ).fetchall()
            except sqlite3.Error:
                raise storage() from None

            # Verify and rewrap every envelope before any write. A single bad
            # envelope aborts the whole request with nothing changed.
            rewrapped: list[tuple] = []
            for row in rows:
                try:
                    new_wrap_nonce, new_wrapped = envelope.rewrap(
                        self._keys, row["tenant"], row["id"], row, target
                    )
                except envelope.EnvelopeIntegrityError:
                    raise integrity() from None
                rewrapped.append((new_wrap_nonce, new_wrapped, target, row["tenant"], row["id"]))

            try:
                with self._connection:
                    for new_wrap_nonce, new_wrapped, version, tenant, record_id in rewrapped:
                        self._connection.execute(
                            "UPDATE records SET wrap_nonce=?, wrapped_key=?, key_version=? "
                            "WHERE tenant=? AND id=?",
                            (new_wrap_nonce, new_wrapped, version, tenant, record_id),
                        )
                    self._connection.execute(
                        "UPDATE service_metadata SET value=? WHERE name='active_version'",
                        (str(target),),
                    )
            except sqlite3.Error:
                raise storage() from None

            self._active_version = target
            return target, len(rewrapped)

"""Read local service configuration without exposing secret values."""

import base64
import binascii
import json
from dataclasses import dataclass
from pathlib import Path


@dataclass(frozen=True)
class Config:
    database: Path
    active_version: int
    keys: dict[int, bytes]


def load_config(database: str | Path, keyring: str | Path) -> Config:
    try:
        raw = json.loads(Path(keyring).read_text(encoding="utf-8"))
        active = raw["active_version"]
        if type(active) is not int or active < 1:
            raise ValueError("invalid active version")
        encoded_keys = raw["keys"]
        if not isinstance(encoded_keys, dict) or not encoded_keys:
            raise ValueError("empty key set")
        keys = {}
        for name, encoded in encoded_keys.items():
            if not isinstance(name, str) or not name.isascii() or not name.isdecimal():
                raise ValueError("invalid version")
            version = int(name)
            if version < 1 or str(version) != name or not isinstance(encoded, str):
                raise ValueError("invalid key entry")
            material = base64.b64decode(encoded, validate=True)
            if len(material) != 32:
                raise ValueError("invalid key length")
            keys[version] = material
        if active not in keys:
            raise ValueError("active version unavailable")
        return Config(Path(database).resolve(), active, keys)
    except (OSError, ValueError, TypeError, KeyError, binascii.Error) as exc:
        raise ValueError("Invalid keyring configuration") from exc

